import{_ as t,a,o as r,a6 as s}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Send a Return Message","description":"","frontmatter":{"outline":false,"examples":[{"id":"send-return-message","title":"Send a Return Message","description":"Add a customer message to the conversation thread of a return (RMA) request.","query":"mutation CreateCustomerReturnMessage(\\n  $returnId: Int!\\n  $message: String!\\n) {\\n  createCustomerReturnMessage(\\n    input: {\\n      returnId: $returnId\\n      message: $message\\n    }\\n  ) {\\n    customerReturnMessage {\\n      _id\\n      rmaId\\n      message\\n      isAdmin\\n      attachment\\n      attachmentUrl\\n      createdAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"returnId\\": 12,\\n  \\"message\\": \\"Any update on my return?\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createCustomerReturnMessage\\": {\\n      \\"customerReturnMessage\\": {\\n        \\"_id\\": 89,\\n        \\"rmaId\\": 12,\\n        \\"message\\": \\"Any update on my return?\\",\\n        \\"isAdmin\\": false,\\n        \\"attachment\\": null,\\n        \\"attachmentUrl\\": null,\\n        \\"createdAt\\": \\"2026-07-20T11:15:00+00:00\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"message required","cause":"The message field is missing","solution":"Provide a non-empty message"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"NOT_FOUND","cause":"The return does not exist or is not owned by the authenticated customer","solution":"Only return IDs belonging to the logged-in customer can be messaged"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/mutations/send-return-message.md","filePath":"api/graphql-api/shop/returns/mutations/send-return-message.md","lastUpdated":1787725411000}'),n={name:"api/graphql-api/shop/returns/mutations/send-return-message.md"};function d(o,e,i,u,c,h){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="send-a-return-message" tabindex="-1">Send a Return Message <a class="header-anchor" href="#send-a-return-message" aria-label="Permalink to &quot;Send a Return Message&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>createCustomerReturnMessage</code> mutation adds a customer message to the conversation thread of a return (RMA) request. The return must belong to the authenticated customer. The created message comes back flagged <code>isAdmin: false</code>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>returnId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Id of the return to add the message to. Must belong to the authenticated customer.</td></tr><tr><td><code>message</code></td><td><code>String!</code></td><td>✅ Yes</td><td>The message text.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>customerReturnMessage._id</code></td><td><code>Int!</code></td><td>Numeric message id.</td></tr><tr><td><code>customerReturnMessage.rmaId</code></td><td><code>Int!</code></td><td>Id of the return the message belongs to.</td></tr><tr><td><code>customerReturnMessage.message</code></td><td><code>String!</code></td><td>The message text.</td></tr><tr><td><code>customerReturnMessage.isAdmin</code></td><td><code>Boolean!</code></td><td><code>false</code> — the message was sent by the customer.</td></tr><tr><td><code>customerReturnMessage.attachment</code></td><td><code>String</code></td><td>Stored attachment path, or <code>null</code>.</td></tr><tr><td><code>customerReturnMessage.attachmentUrl</code></td><td><code>String</code></td><td>Public URL of the attachment, or <code>null</code>.</td></tr><tr><td><code>customerReturnMessage.createdAt</code></td><td><code>DateTime!</code></td><td>Message timestamp.</td></tr></tbody></table><p>Attaching a file to a message is REST-only, through a multipart <code>file</code> field — a JSON GraphQL request cannot carry a file. Send the text here, and use REST when the shopper attaches something.</p><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/queries/list-return-messages.html">List Return Messages</a></li><li><a href="/api/graphql-api/shop/returns/queries/view-return.html">View Return</a></li><li><a href="/api/graphql-api/shop/returns/">Returns Overview</a></li></ul>',12)]))}const g=t(n,[["render",d]]);export{m as __pageData,g as default};
